import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec2, mix, Fn, fract, sin, float, uniform, texture, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = new THREE.Color(colors.ink ?? '#16161d');
  const paper = new THREE.Color(colors.paper ?? '#e8ecf2');
  const accent = new THREE.Color(colors.accent ?? '#ff2a38');
  const surface = new THREE.Color(colors.surface ?? '#0b0b10');

  // CTA panel dimensions (sits at bottom of hub composition)
  const W = 2.6;
  const H = 0.56;
  const panelGeo = new THREE.PlaneGeometry(W, H, 1, 1);

  // Fallback 1x1 white texture so the texture() node is never null
  const fallbackTex = new THREE.DataTexture(new Uint8Array([255, 255, 255, 255]), 1, 1);
  fallbackTex.needsUpdate = true;
  const metalTexUniform = uniform(fallbackTex);

  // Engineered gradient + brushed-metal overlay + grain (TSL only)
  const panelMat = new MeshBasicNodeMaterial();
  panelMat.colorNode = Fn(() => {
    const u = uv();

    // vertical engineered gradient: surface -> ink (subtle lift at top edge)
    const grad = mix(vec3(surface), vec3(ink), smoothstep(float(0.0), float(1.0), u.y.mul(0.85).add(0.1)));

    // brushed-metal texture sampled and tuned dark so it reads as a machined plate
    const mt = texture(metalTexUniform, u);
    const brushed = mt.rgb.mul(0.55);
    const blended = mix(grad, brushed.add(grad.mul(0.4)), float(0.55));

    // subtle anisotropic streak emulation via horizontal modulation
    const streak = sin(u.x.mul(180.0)).mul(0.012);
    const base = blended.add(vec3(streak));

    // film grain
    const seed = u.mul(vec2(1024.0, 512.0));
    const g = fract(sin(seed.dot(vec2(12.9898, 78.233))).mul(43758.5453));
    const grain = g.sub(0.5).mul(0.025);

    // soft vignette at the edges to read as a machined inset
    const edge = smoothstep(float(0.0), float(0.06), u.x).mul(smoothstep(float(0.0), float(0.06), float(1.0).sub(u.x)))
      .mul(smoothstep(float(0.0), float(0.18), u.y)).mul(smoothstep(float(0.0), float(0.18), float(1.0).sub(u.y)));
    const vignetted = base.mul(edge.mul(0.55).add(0.45));

    return vignetted.add(vec3(grain));
  })();

  const panel = new THREE.Mesh(panelGeo, panelMat);
  group.add(panel);

  // Async swap-in of the brushed metal map
  ctx.textureLoader.loadTexture(config.imageUrl ?? '/prism-assets/chrome/brushed-metal.map.png').then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.ClampToEdgeWrapping;
    tex.needsUpdate = true;
    metalTexUniform.value = tex;
  });

  // Accent signal bar on the left edge (<=10% of frame area)
  const accentGeo = new THREE.PlaneGeometry(0.035, H * 0.62);
  const accentMat = new MeshBasicNodeMaterial();
  accentMat.colorNode = vec3(accent);
  const accentBar = new THREE.Mesh(accentGeo, accentMat);
  accentBar.position.set(-W / 2 + 0.11, 0.0, 0.012);
  group.add(accentBar);

  // Thin paper-tone divider line under text for engineered finish
  const dividerGeo = new THREE.PlaneGeometry(W * 0.78, 0.004);
  const dividerMat = new MeshBasicNodeMaterial();
  dividerMat.colorNode = vec3(paper).mul(0.18);
  const divider = new THREE.Mesh(dividerGeo, dividerMat);
  divider.position.set(0.08, -H * 0.28, 0.012);
  group.add(divider);

  // Text content — render spec copy verbatim via ctx.fontAtlas
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? 42;
    const label = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize,
      color: paper.getHex(),
      align: 'center',
      letterSpacingPx: 1.2,
    });
    label.position.set(0.06, 0.02, 0.02);
    group.add(label);
  }

  // No interactions per spec, but expose handlers surface for the adapter contract
  group.userData.handlers = {};

  group.userData.cleanup = () => {
    panelGeo.dispose();
    panelMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    if (fallbackTex) fallbackTex.dispose();
  };

  return group;
}
